use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let jobs = input["jobs"].as_array().unwrap();
    let quantum = input["quantum"].as_i64().unwrap();
    let mut jobs = jobs.iter().enumerate().map(|(i, &work)| (i, work as i64)).collect::<Vec<_>>();
    let mut result = Vec::new();
    let mut time = 0;

    while !jobs.is_empty() {
        for i in 0..jobs.len() {
            let (job_index, work) = &mut jobs[i];
            if *work > 0 {
                if *work <= quantum {
                    result.push(*job_index);
                    *work = 0;
                } else {
                    *work -= quantum;
                }
            }
        }
        time += quantum;
    }

    json!(result)
}
